export const getReadTestProgressProjectsProjectIdTestDesignsDesignIdProgressGetUrl =
  (
    projectId: number,
    designId: number,
    params?: ReadTestProgressProjectsProjectIdTestDesignsDesignIdProgressGetParams,
  ) => {
    const normalizedParams = new URLSearchParams();

    Object.entries(params || {}).forEach(([key, value]) => {
      if (value !== undefined) {
        normalizedParams.append(key, value === null ? "null" : String(value));
      }
    });

    const stringifiedParams = normalizedParams.toString();

    return stringifiedParams.length > 0
      ? `/projects/${projectId}/test-designs/${designId}/progress?${stringifiedParams}`
      : `/projects/${projectId}/test-designs/${designId}/progress`;
  };

